!function(){"use strict";document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll(".fade-in-on-scroll"),t=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{root:null,rootMargin:"0px",threshold:.15});e.forEach(e=>{t.observe(e)})})}();